package com.periodicelements;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads the element and substance tables bundled in the jar.
 * Both are generated by tools/generate.py from the CSV files in data/.
 */
public final class ElementTable {
	private ElementTable() {
	}

	public static List<Element> load() {
		JsonArray array = read("/periodic_elements/elements.json");
		List<Element> elements = new ArrayList<>(array.size());
		for (JsonElement entry : array) {
			JsonObject o = entry.getAsJsonObject();
			elements.add(new Element(
					o.get("id").getAsString(),
					o.get("number").getAsInt(),
					o.get("symbol").getAsString(),
					o.get("name").getAsString(),
					o.get("state").getAsString(),
					o.get("category").getAsString(),
					Integer.parseInt(o.get("color").getAsString(), 16),
					o.get("level").getAsInt(),
					o.get("discovered").getAsString()
			));
		}
		return Collections.unmodifiableList(elements);
	}

	/** Substances in simple-to-complex order. */
	public static List<Substance> loadSubstances() {
		JsonArray array = read("/periodic_elements/substances.json");
		List<Substance> substances = new ArrayList<>(array.size());
		for (JsonElement entry : array) {
			JsonObject o = entry.getAsJsonObject();
			Map<String, Integer> composition = new LinkedHashMap<>();
			for (Map.Entry<String, JsonElement> atom : o.getAsJsonObject("composition").entrySet()) {
				composition.put(atom.getKey(), atom.getValue().getAsInt());
			}
			substances.add(new Substance(
					o.get("id").getAsString(),
					o.get("name").getAsString(),
					o.get("formula").getAsString(),
					o.get("state").getAsString(),
					o.get("sector").getAsString(),
					o.get("tier").getAsInt(),
					o.get("level").getAsInt(),
					Integer.parseInt(o.get("color").getAsString(), 16),
					Collections.unmodifiableMap(composition)
			));
		}
		return Collections.unmodifiableList(substances);
	}

	/** Block or item id (e.g. "minecraft:andesite") to its rarity-corrected composition in units. */
	public static Map<String, BlockComposition.Entry> loadCompositions() {
		JsonObject root = readObject("/periodic_elements/compositions.json");
		Map<String, BlockComposition.Entry> out = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : root.entrySet()) {
			JsonObject value = entry.getValue().getAsJsonObject();
			List<BlockComposition.Part> parts = new ArrayList<>();
			for (JsonElement p : value.getAsJsonArray("parts")) {
				JsonObject o = p.getAsJsonObject();
				parts.add(new BlockComposition.Part(o.get("id").getAsString(), o.get("units").getAsDouble()));
			}
			out.put(entry.getKey(), new BlockComposition.Entry(value.get("amount").getAsDouble(),
					Collections.unmodifiableList(parts)));
		}
		return Collections.unmodifiableMap(out);
	}

	public static JsonArray readArray(String resource) {
		return parse(resource).getAsJsonArray();
	}

	private static JsonArray read(String resource) {
		return readArray(resource);
	}

	public static JsonObject readObject(String resource) {
		return parse(resource).getAsJsonObject();
	}

	private static JsonElement parse(String resource) {
		try (InputStream in = ElementTable.class.getResourceAsStream(resource)) {
			if (in == null) {
				throw new IllegalStateException("Missing " + resource + " in the mod jar");
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
				return JsonParser.parseReader(reader);
			}
		} catch (IOException e) {
			throw new IllegalStateException("Could not read " + resource, e);
		}
	}
}
